import{_ as t,o as n,c as s,a2 as r}from"./chunks/framework.Bg-Zxr5O.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-en/String-Functions.md","filePath":"manual-en/String-Functions.md","lastUpdated":1785684581000}'),o={name:"manual-en/String-Functions.md"};function i(a,e,g,c,d,u){return n(),s("div",null,[...e[0]||(e[0]=[r('<h4 id="_7-7-7-string-functions" tabindex="-1">7.7.7 String Functions <a class="header-anchor" href="#_7-7-7-string-functions" aria-label="Permalink to &quot;7.7.7 String Functions&quot;">​</a></h4><p>String functions take various arguments and return various results.</p><p>Function: __<strong>CONCAT</strong> <em>( string, string[, …])</em></p><p>Returns a string consisting of each string in sequence. <code>CONCAT(&quot;abc&quot;, &quot;def&quot;, &quot;ghi&quot;)</code> has a value of <code>&quot;abcdefghi&quot;</code>. The resultant string is truncated to a maximum of 32767 bytes.</p><p>Function: __<strong>INDEX</strong> <em>( haystack, needle)</em> Function: __<strong>RINDEX</strong> <em>( haystack, needle)</em></p><p>Returns a positive integer indicating the position of the first (for <code>INDEX</code>) or last (for <code>RINDEX</code>) occurrence of needle in haystack. Returns 0 if haystack does not contain needle. Returns 1 if needle is the empty string.</p><p>Function: __<strong>INDEX</strong> <em>( haystack, needles, needle_len)</em> Function: __<strong>RINDEX</strong> <em>( haystack, needle, needle_len)</em></p><p>Divides needles into multiple needles, each with length needle_len, which must be a positive integer that evenly divides the length of needles. Searches haystack for the occurrences of each needle and returns a positive integer indicating the byte index of the beginning of the first (for <code>INDEX</code>) or last (for <code>RINDEX</code>) needle it finds. Returns 0 if haystack does not contain any of the needles, or if needles is the empty string.</p><p>Function: __<strong>LENGTH</strong> <em>( string)</em></p><p>Returns the number of bytes in string.</p><p>Function: __<strong>LOWER</strong> <em>( string)</em></p><p>Returns a string identical to string except that all uppercase letters are changed to lowercase letters. The definitions of “uppercase” and “lowercase” are system-dependent.</p><p>Function: __<strong>LPAD</strong> <em>( string, length[, padding])</em> Function: __<strong>RPAD</strong> <em>( string, length[, padding])</em></p><p>If string is at least length bytes long, these functions return string unchanged. Otherwise, they return string padded with padding on the left side (for <code>LPAD</code>) or right side (for <code>RPAD</code>) to length bytes. These functions report an error and return string unchanged if length is missing or bigger than 32767.</p><p>The padding argument must not be an empty string and defaults to a space if not specified. If its length does not evenly fit the amount of space needed for padding, the returned string will be shorter than length.</p><p>Function: __<strong>LTRIM</strong> <em>( string[, padding])</em> Function: __<strong>RTRIM</strong> <em>( string[, padding])</em></p><p>These functions return string, after removing leading (for <code>LTRIM</code>) or trailing (for <code>RTRIM</code>) copies of padding. If padding is omitted, these functions remove spaces (but not tabs or other white space). These functions return string unchanged if padding is the empty string.</p><p>Function: __<strong>NUMBER</strong> <em>( string, format)</em></p><p>Returns the number produced when string is interpreted according to format specifier format. If the format width w is less than the length of string, then only the first w bytes in string are used, <em>e.g.</em> <code>NUMBER(&quot;123&quot;, F3.0)</code> and <code>NUMBER(&quot;1234&quot;, F3.0)</code> both have value 123. If w is greater than string’s length, then it is treated as if it were right-padded with spaces. If string is not in the correct format for format, system-missing is returned.</p><p>Function: __<strong>REPLACE</strong> <em>( haystack, needle, replacement[, n])</em></p><p>Returns string haystack with instances of needle replaced by replacement. If nonnegative integer n is specified, it limits the maximum number of replacements; otherwise, all instances of needle are replaced.</p><p>Function: __<strong>STRING</strong> <em>( number, format)</em></p><p>Returns a string corresponding to number in the format given by format specifier format. For example, <code>STRING(123.56, F5.1)</code> has the value <code>&quot;123.6&quot;</code>.</p><p>Function: __<strong>STRUNC</strong> <em>( string, n)</em></p><p>Returns string, first trimming it to at most n bytes, then removing trailing spaces (but not tabs or other white space). Returns an empty string if n is zero or negative, or string unchanged if n is missing.</p><p>Function: __<strong>SUBSTR</strong> <em>( string, start)</em></p><p>Returns a string consisting of the value of string from position start onward. Returns an empty string if start is system-missing, less than 1, or greater than the length of string.</p><p>Function: __<strong>SUBSTR</strong> <em>( string, start, count)</em></p><p>Returns a string consisting of the first count bytes from string beginning at position start. Returns an empty string if start or count is system-missing, if start is less than 1 or greater than the number of bytes in string, or if count is less than 1. Returns a string shorter than count bytes if start + count - 1 is greater than the number of bytes in string. Examples: <code>SUBSTR(&quot;abcdefg&quot;, 3, 2)</code> has value <code>&quot;cd&quot;</code>; <code>SUBSTR(&quot;nonsense&quot;, 4, 10)</code> has the value <code>&quot;sense&quot;</code>.</p><p>Function: __<strong>UPCASE</strong> <em>( string)</em></p><p>Returns string, changing lowercase letters to uppercase letters.</p>',31)])])}const m=t(o,[["render",i]]);export{h as __pageData,m as default};
